@testable import Resting

final class RestingErrorMappingTests: XCTestCase {
    private var configuration: URLSessionConfiguration!

    override func setUp() {
        super.setUp()
        configuration = URLSessionConfiguration.ephemeral
        configuration.protocolClasses = [MockURLProtocol.self]
        MockURLProtocol.reset()
    }

    override func tearDown() {
        MockURLProtocol.reset()
        configuration = nil
        super.tearDown()
    }

    func testTransportErrorsMapToTypedFailure() async {
        MockURLProtocol.setRequestHandler { request in
            .init(
                response: HTTPURLResponse(
                    url: try XCTUnwrap(request.url),
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: nil
                )!,
                error: URLError(.notConnectedToInternet)
            )
        }

        let client = RestClient(
            configuration: RestClientConfiguration(sessionConfiguration: configuration)
        )

        do {
            _ = try await client.executeData(.query(url: URL(string: "https://example.com/articles")!))
            XCTFail("Request should have failed.")
        } catch let error as RestingError {
            guard case .transport(let urlError) = error else {
                return XCTFail("Expected transport error, got \(error)")
            }
            XCTAssertEqual(urlError.code, .notConnectedToInternet)
        } catch {
            XCTFail("Unexpected error: \(error)")
        }
    }

    func testInvalidResponsesMapToTypedFailure() async {
        MockURLProtocol.setRequestHandler { request in
            .init(
                response: URLResponse(
                    url: try XCTUnwrap(request.url),
                    mimeType: "text/plain",
                    expectedContentLength: 0,
                    textEncodingName: nil
                )
            )
        }

        let client = RestClient(
            configuration: RestClientConfiguration(sessionConfiguration: configuration)
        )

        do {
            _ = try await client.executeData(.query(url: URL(string: "https://example.com/articles")!))
            XCTFail("Request should have failed.")
        } catch let error as RestingError {
            guard case .invalidResponse = error else {
                return XCTFail("Expected invalid response error, got \(error)")
            }
        } catch {
            XCTFail("Unexpected error: \(error)")
        }
    }

    func testStatusCodeFailuresRetainStatusCodeAndBody() async {
        let responseBody = Data("{\"error\":\"missing\"}".utf8)
        MockURLProtocol.setRequestHandler { request in
            .init(
                response: HTTPURLResponse(
                    url: try XCTUnwrap(request.url),
                    statusCode: 404,
                    httpVersion: nil,
                    headerFields: nil
                )!,
                data: responseBody
            )
        }

        let client = RestClient(
            configuration: RestClientConfiguration(sessionConfiguration: configuration)
        )

        do {
            _ = try await client.executeData(.query(url: URL(string: "https://example.com/articles")!))
            XCTFail("Request should have failed.")
        } catch let error as RestingError {
            guard case .statusCode(let statusCode, let data) = error else {
                return XCTFail("Expected status code error, got \(error)")
            }
            XCTAssertEqual(statusCode, 404)
            XCTAssertEqual(data, responseBody)
        } catch {
            XCTFail("Unexpected error: \(error)")
        }
    }

    func testDecodingFailuresMapToTypedFailure() async {
        struct Article: Decodable {
            let title: String
        }

        MockURLProtocol.setRequestHandler { request in
            .init(
                response: HTTPURLResponse(
                    url: try XCTUnwrap(request.url),
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: nil
                )!,
                data: Data("{\"wrong\":\"shape\"}".utf8)
            )
        }

        let client = RestClient(
            configuration: RestClientConfiguration(sessionConfiguration: configuration)
        )

        do {
            let _: Article = try await client.execute(
                .query(url: URL(string: "https://example.com/articles")!),
                as: Article.self
            )
            XCTFail("Decoding should have failed.")
        } catch let error as RestingError {
            guard case .decoding = error else {
                return XCTFail("Expected decoding error, got \(error)")
            }
        } catch {
            XCTFail("Unexpected error: \(error)")
        }
    }

    func testDownloadCancellationMapsToTypedFailure() async {
        MockURLProtocol.setRequestHandler { request in
            .init(
                response: HTTPURLResponse(
                    url: try XCTUnwrap(request.url),
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: nil
                )!,
                data: DownloadFixture.data,
                delay: 0.25
            )
        }

        let client = RestClient(
            configuration: RestClientConfiguration(sessionConfiguration: configuration)
        )
        let handle = client.download(.download(url: URL(string: "https://example.com/cancel.txt")!))
        handle.cancel()

        do {
            _ = try await handle.value
            XCTFail("Cancelled handle should not succeed.")
        } catch let error as RestingError {
            guard case .cancelled = error else {
                return XCTFail("Expected cancelled error, got \(error)")
            }
        } catch {
            XCTFail("Unexpected error: \(error)")
        }
    }
}

import XCTest
@testable import Resting

final class RequestDefinitionTests: XCTestCase {
    func testQueryRequestBuildsQueryItemsAndMethod() throws {
        let request = RequestDefinition.query(
            url: URL(string: "https://example.com/articles")!,
            method: .get,
            queryItems: [
                URLQueryItem(name: "page", value: "1"),
                URLQueryItem(name: "sort", value: "recent"),
            ],
            headers: ["Accept": "application/json"]
        )

        let urlRequest = try request.makeURLRequest(defaultHeaders: [:], encoder: JSONEncoder())

        XCTAssertEqual(urlRequest.httpMethod, "GET")
        XCTAssertEqual(urlRequest.url?.query, "page=1&sort=recent")
        XCTAssertEqual(urlRequest.value(forHTTPHeaderField: "Accept"), "application/json")
        XCTAssertNil(urlRequest.httpBody)
    }

    func testFormRequestEncodesBodyAndContentType() throws {
        let request = RequestDefinition.form(
            url: URL(string: "https://example.com/login")!,
            fields: [
                "email": "hello@example.com",
                "password": "p@ss word",
            ]
        )

        let urlRequest = try request.makeURLRequest(defaultHeaders: [:], encoder: JSONEncoder())
        let bodyString = try XCTUnwrap(String(data: XCTUnwrap(urlRequest.httpBody), encoding: .utf8))

        XCTAssertEqual(urlRequest.httpMethod, "POST")
        XCTAssertEqual(
            bodyString,
            "email=hello@example.com&password=p%40ss%20word"
        )
        XCTAssertEqual(
            urlRequest.value(forHTTPHeaderField: "Content-Type"),
            "application/x-www-form-urlencoded; charset=utf-8"
        )
    }

    func testJSONRequestUsesConfiguredEncoder() throws {
        struct CreateArticleRequest: Encodable {
            let title: String
            let createdAt: Date
        }

        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601

        let request = RequestDefinition.json(
            url: URL(string: "https://example.com/articles")!,
            body: CreateArticleRequest(
                title: "Modern API",
                createdAt: Date(timeIntervalSince1970: 0)
            )
        )

        let urlRequest = try request.makeURLRequest(defaultHeaders: [:], encoder: encoder)
        let bodyData = try XCTUnwrap(urlRequest.httpBody)
        let bodyObject = try JSONSerialization.jsonObject(with: bodyData) as? [String: String]

        XCTAssertEqual(urlRequest.value(forHTTPHeaderField: "Content-Type"), "application/json")
        XCTAssertEqual(bodyObject?["title"], "Modern API")
        XCTAssertEqual(bodyObject?["createdAt"], "1970-01-01T00:00:00Z")
    }

    func testRawRequestRequiresExplicitContentType() {
        let request = RequestDefinition.raw(
            url: URL(string: "https://example.com/upload")!,
            body: Data("payload".utf8),
            contentType: ""
        )

        XCTAssertThrowsError(
            try request.makeURLRequest(defaultHeaders: [:], encoder: JSONEncoder())
        ) { error in
            guard case RestingError.invalidRequest = error else {
                return XCTFail("Expected invalid request error, got \(error)")
            }
        }
    }

    func testRequestHeadersOverrideDefaultsAndAutomaticHeaders() throws {
        let request = RequestDefinition.jsonData(
            url: URL(string: "https://example.com/articles")!,
            body: Data("{}".utf8),
            headers: [
                "Authorization": "Bearer request-token",
                "Content-Type": "application/vnd.api+json",
            ]
        )

        let urlRequest = try request.makeURLRequest(
            defaultHeaders: [
                "Authorization": "Bearer default-token",
                "Accept": "application/json",
            ],
            encoder: JSONEncoder()
        )

        XCTAssertEqual(urlRequest.value(forHTTPHeaderField: "Accept"), "application/json")
        XCTAssertEqual(urlRequest.value(forHTTPHeaderField: "Authorization"), "Bearer request-token")
        XCTAssertEqual(urlRequest.value(forHTTPHeaderField: "Content-Type"), "application/vnd.api+json")
    }
}

import XCTest
@testable import Resting

final class TransferHandleTests: XCTestCase {
    private var configuration: URLSessionConfiguration!

    override func setUp() {
        super.setUp()
        configuration = URLSessionConfiguration.ephemeral
        configuration.protocolClasses = [MockURLProtocol.self]
        MockURLProtocol.reset()
    }

    override func tearDown() {
        MockURLProtocol.reset()
        configuration = nil
        super.tearDown()
    }

    func testDownloadReportsProgressAndMovesFile() async throws {
        MockURLProtocol.setRequestHandler { request in
            .init(
                response: HTTPURLResponse(
                    url: try XCTUnwrap(request.url),
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: nil
                )!,
                data: DownloadFixture.data
            )
        }

        let client = RestClient(
            configuration: RestClientConfiguration(sessionConfiguration: configuration)
        )
        let handle = client.download(.download(url: URL(string: "https://example.com/archive.txt")!))

        var lastFractionCompleted: Double = 0
        handle.observeProgress { progress in
            lastFractionCompleted = progress.fractionCompleted
        }

        let fileURL = try await handle.value

        XCTAssertEqual(try DownloadFixture.readString(from: fileURL), DownloadFixture.text)
        XCTAssertEqual(handle.state, .completed)
        XCTAssertEqual(lastFractionCompleted, 1)
    }

    func testCancellingOneTransferDoesNotAffectAnother() async throws {
        MockURLProtocol.setRequestHandler { request in
            let delay: TimeInterval = request.url?.lastPathComponent == "slow.txt" ? 0.25 : 0.01
            let body = Data(request.url!.lastPathComponent.utf8)
            return .init(
                response: HTTPURLResponse(
                    url: try XCTUnwrap(request.url),
                    statusCode: 200,
                    httpVersion: nil,
                    headerFields: nil
                )!,
                data: body,
                delay: delay
            )
        }

        let client = RestClient(
            configuration: RestClientConfiguration(sessionConfiguration: configuration)
        )
        let slowHandle = client.download(.download(url: URL(string: "https://example.com/slow.txt")!))
        let fastHandle = client.download(.download(url: URL(string: "https://example.com/fast.txt")!))

        slowHandle.cancel()

        let fastFileURL = try await fastHandle.value
        XCTAssertEqual(try DownloadFixture.readString(from: fastFileURL), "fast.txt")
        XCTAssertEqual(fastHandle.state, .completed)

        do {
            _ = try await slowHandle.value
            XCTFail("Cancelled transfer should not succeed.")
        } catch let error as RestingError {
            guard case .cancelled = error else {
                return XCTFail("Expected cancelled error, got \(error)")
            }
        }
    }
}

